@prefix ns2: <http://www.w3.org/2003/06/sw-vocab-status/ns#> .
@prefix ns3: <http://www.cidoc-crm.org/cidoc-crm/> .
@prefix schema: <https://schema.org/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .

<http://example.org/Atrium> rdf:type ns3:E53_Place ;
    schema:description "The well was located in the atrium of the domus, the 'public' part of the house." .

<http://example.org/Domus> rdf:type ns2:CACAO_0000055 ;
    ns3:P89i_contains <http://example.org/Atrium> .

<http://example.org/ImpluviumBasin> rdf:type ns3:E24_Physical_Human-Made_Thing ;
    schema:description "In the center of the atrium there was the impluvium basin (now rebuilt) with a well." .

<http://example.org/Wellhead> rdf:type ns3:E24_Physical_Human-Made_Thing ;
    schema:description "The wellhead, i.e. the protective balustrade closed around the hole of a well, was partially found." .

<http://example.org/Well> rdf:type ns3:E19_Physical_Object ;
    ns3:P55_has_current_location <http://example.org/Atrium> ;
    schema:description "The well was not very deep because the aquifer in Aquileia is almost at ground level." .

<http://example.org/Aquileia> rdf:type schema:Place ;
    schema:description "Aquileia" .

<http://example.org/3DPrintingTechniques> rdf:type ns3:E55_Type ;
    schema:description "3D printing techniques" .

<http://example.org/ReconstructionEvent> rdf:type ns3:E7_Activity ;
    ns3:P14_carried_out_by <http://example.org/3DPrintingTechniques> ;
    ns3:P12_occurred_in_the_presence_of <http://example.org/Wellhead> ;
    schema:description "The missing part was then reconstructed with 3D printing techniques." .

<http://example.org/Aquifer> rdf:type ns3:E70_Thing ;
    ns3:P55_has_current_location <http://example.org/Aquileia> .
